# Actual corporate/commitment source bindings, reference comparisons and frozen replay.
run_wholesale_sme_journey_review<-function(data=NULL,verify_reference=TRUE,accounts_path=NULL,releases_path=NULL,corporate_data=NULL,commitment_data=NULL,observed_data=NULL,artifact_paths=NULL,return_artifacts=FALSE,engine_paths=NULL){
 resource<-function(name)system.file('extdata',name,package='creditratingsystem');read<-function(name)jsonlite::fromJSON(resource(paste0(name,'.json')),simplifyVector=FALSE)
 if(is.null(data))data<-read('wholesale_sme_journey_review');if(is.null(corporate_data))corporate_data<-read('wholesale_corporate_lifecycle');if(is.null(commitment_data))commitment_data<-read('wholesale_commitment_governance');if(is.null(observed_data))observed_data<-read('wholesale_commitment_observed')
 helper<-function(name){path<-if(is.null(engine_paths))system.file('examples',paste0(name,'.R'),package='creditratingsystem')else engine_paths[[name]];env<-new.env(parent=environment());sys.source(path,env);env}
 le<-helper('input_lineage');lineage<-le$prepare_input_snapshot(if(is.null(accounts_path))resource('wholesale_sme_positions.csv')else accounts_path,if(is.null(releases_path))resource('wholesale_sme_releases.csv')else releases_path,data$lineage_config,data$lineage_config$cutoffs[[1]]);rows<-setNames(lineage$rows,vapply(lineage$rows,function(x)x$entity_id,character(1)));tools<-helper('_wholesale_journey_tools');out<-list();audits<-list()
 for(case in data$cases){
  sid<-case$case_id;source<-rows[[sid]]
  if(source$balance!=case$source_balance||source$product_id!=case$product||source$x!=case$source_feature)stop('Source must bind actual exposure, product and frozen financial input')
  model<-load_fitted_model(if(is.null(artifact_paths))resource(case$model_resource)else artifact_paths[[case$model_resource]])
  if(case$product=='CORPORATE_LOAN_BOND'){
   if(sid!=corporate_data$subject_id||source$balance!=corporate_data$positions[[1]]$ead||source$x!=2)stop('Corporate source differs from original historical subject/claim')
   engine<-helper('wholesale_corporate_lifecycle');audit<-engine$.wholesale_corporate_governance(corporate_data,list(model=model$value),return_audit_artifacts=TRUE);policy<-compile_credit_decision_policy(corporate_data$decision_policy)$value;timing<-list(as_of='2024-01-01',known_at='2024-01-01');p<-audit$report$origination_pd;gate<-corporate_data$credit_gate_inputs
   decision<-apply_credit_decision_policy(policy,risk=c(timing,list(pd=p,target=case$target,freshness='CURRENT')),affordability=c(timing,list(status=if(gate$available_cashflow>=gate$debt_service_due)'AFFORDABLE'else'NOT_AFFORDABLE')),eligibility=c(timing,list(status=if(gate$legal_eligibility)'ELIGIBLE'else'INELIGIBLE')),operations=c(timing,list(status=gate$operations_status)),as_of=timing$as_of,known_at=timing$known_at)$value
   reference<-corporate_data$monitoring$predictions[[1]]$pd;stopifnot(all(vapply(corporate_data$monitoring$predictions,function(x)x$pd==reference,logical(1))));prediction_case<-case;prediction_case$features<-list(list(source$x));prediction_case$feature_order<-corporate_data$development$feature_order;prediction_case$reference_pd<-reference;prediction_case$calibrator<-list(applied=FALSE,reference='Previously recorded fixed reference forecasts; no separate calibration applied');observed<-list(monitoring=corporate_data$monitoring);reference_id<-'recorded_reference';defaults<-2;mature<-20
  }else{
   c<-Filter(function(x)x$case_id==sid,commitment_data$cases)[[1]];journeys<-unlist(lapply(observed_data$cohorts,function(x)x$journeys),recursive=FALSE);j<-Filter(function(x)x$case_id==sid,journeys)[[1]]
   if(source$x!=c$features[[1]][[1]]||!identical(j$forecast_contract$target,c$target))stop('Commitment source/observed target differs from pinned historical forecast')
   c$features<-list(list(source$x));subset<-commitment_data;subset$cases<-list(c);engine<-helper('wholesale_sector_governance');result<-engine$run_wholesale_sector_governance(subset,artifact_paths=artifact_paths,return_audit_artifacts=TRUE);audit<-result$audits[[1]];audit$report<-result$report$cases[[1]];decision<-audit$results[[1]]$value$decision;policy<-audit$registry$entries[[1]]$bundle$dependencies$artifacts$credit_policy$content;prediction_case<-c;observed<-j;reference_id<-'calibrated';defaults<-j$cohort_defaults;mature<-20
   forecast<-j$forecast_contract;raw<-predict_pd(model,do.call(rbind,lapply(forecast$features,unlist)),feature_order=unlist(forecast$feature_order),expected_target=forecast$target)$value;args<-c(list(calibrator=forecast$calibrator,values=raw,target=forecast$target,base_model_version='1'),forecast$calibrator_arguments);cal<-do.call(apply_calibrator,args)$value[[1]]
   if(abs(cal-c$reference_pd)>1e-12||any(vapply(j$monitoring$predictions,function(x)abs(x$pd-cal)>1e-12,logical(1))))stop('Observed forecast must equal actual calibrated pinned inference')
  }
  reason<-setNames(lapply(decision$rule_trace,function(r)paste0('Declared policy rule ',r$rule_id)),vapply(decision$rule_trace,function(r)r$reason_code,character(1)));explanation<-decompose_policy_decision(decision,reason)$value;replay<-tools$.sector_journey_replay(audit,source,policy);comparison<-tools$.sector_prediction_review(prediction_case,model,observed,reference_id);p<-comparison$raw_pd;oracle<-defaults/mature*(1-p)^2+(1-defaults/mature)*p*p
  if(verify_reference)stopifnot(lineage$audit$decision$status=='PASS',abs(comparison$benchmark$metrics$by_model$raw$brier-oracle)<1e-12)
  out[[length(out)+1L]]<-list(case_id=sid,product=case$product,claim_ids=case$claim_ids,source_balance=source$balance,source_snapshot_hash=lineage$selected_snapshot_hash,target=case$target,governance=audit$report,decision=decision,policy_explanation=explanation,replay=replay$result,negative_replay=replay$negative,prediction_review=comparison,observed_brier_oracle=oracle,observed_mature_count=mature,observed_default_count=defaults);audits[[length(audits)+1L]]<-list(case_id=sid,governance=audit,replay_inputs=replay$inputs)
 }
 report<-list(data_origin='SYNTHETIC',scope=data$scope,lineage=lineage$audit,archive_sha256=lineage$archive_sha256,cases=out)
 if(return_artifacts)list(report=report,artifacts=audits)else report
}
